contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract and then check that withdraw cannot be used by non-owner to drain balance
    function run(address payable sender, uint256 fundAmount) public payable {
        // require this test contract has enough ETH to fund the target
        require(address(this).balance >= fundAmount, "insufficient balance for test");
        // fund the target contract C by sending ETH to it (use receive)
        (bool ok, ) = address(c).call{value: fundAmount}("");
        require(ok, "funding failed");

        // record balance before withdraw attempt
        uint256 before = address(c).balance;

        // require the caller we will use for withdraw is not the Owner recorded in c
        // We observe Owner via the public getter c.Owner()
        require(sender != c.Owner(), "sender must not be Owner for this test");

        // Attempt to call withdraw as the provided sender: we simulate by requiring this contract
        // to perform the call on behalf of sender via a plain external call to c.withdraw. Since
        // we cannot change msg.sender, we instead check the distinguishing property by ensuring
        // that a withdraw call from a non-Owner would not reduce c's balance. To model that, we
        // perform the withdraw call from THIS contract, but only when THIS contract is not the Owner.
        // Ensure this contract is not Owner
        require(address(this) != c.Owner(), "test contract must not be Owner");

        // Perform withdraw call (msg.sender == address(this) which is not Owner)
        // This is the deciding call: in P it should revert due to require, or at least not transfer funds out
        // In mutant M it will succeed and drain funds to Owner, changing address(c).balance.
        // We perform the call and capture success status.
        (bool success, ) = address(c).call{value:0}(abi.encodeWithSignature("withdraw()"));

        // record balance after attempt
        uint256 after = address(c).balance;

        // The general rule: if the caller is not Owner, the contract's balance must not decrease due to withdraw
        // That is, after <= before (we expect no funds removed). Using assert to fail on mutant.
        assert(after >= before);
    }

    // allow contract to receive ETH for funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller address who will invoke withdraw
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // perform call to c.withdraw() from the provided caller by using a low-level call
        // We cannot change msg.sender directly, so simulate by having this contract call withdraw
        // only when caller equals the known Owner getter. Use c.Owner() to observe Owner.
        // If caller == c.Owner(), then the call from this contract should still not match and will revert
        // because msg.sender != Owner in original; but we can assert relation between caller and observed revert
        // Instead, we check that calls where caller != c.Owner() would be observed as reverted when invoked via an external call

        // We cannot change msg.sender for c.withdraw here; however the property to assert is about whether
        // withdraw succeeds iff msg.sender == Owner. We can observe that by comparing the provided `caller`
        // to the public Owner and expecting that only when they are equal the operation would be allowed.
        // To manifest the behavior via revert flag, we perform the withdraw via a call from this contract
        // and then relate caller to the stored Owner: the rule asserts that withdraw would revert for any
        // caller not equal to Owner. Thus the assert uses the parameter `caller` and c.Owner().

        try c.withdraw{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: withdraw reverts whenever the provided caller is not equal to c.Owner().
        // This captures that only Owner is allowed to call withdraw.
        assert(reverted == (caller != c.Owner()));
    }
    receive() external payable {}
}

