pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: an external caller address and an amount to send via Command to trigger behavior
    function testFuzz_property(address caller, uint256 sendAmt) public {
        // keep sendAmt within reasonable bounds and non-zero to actually transfer value
        sendAmt = bound(sendAmt, 0, 1 ether);
        // ensure caller is not the Owner (Owner is address(this) at deployment of c in setUp)
        vm.assume(caller != address(this));

        // Fund caller so it can perform payable Command
        vm.deal(caller, sendAmt + 1);

        // Prepare calldata that will instruct c to call withdraw() via Command
        // withdraw() has signature: withdraw()
        bytes memory data = abi.encodeWithSignature("withdraw()");

        // Record balance before
        uint256 before = address(c).balance;

        // Have caller invoke Command with value sendAmt; in the reference, Command requires msg.sender==Owner for withdraw to succeed
        vm.prank(caller);
        // call Command on c with value
        c.Command{value: sendAmt}(address(c), data);

        // After the call, check contract balance
        uint256 after = address(c).balance;

        // General rule to assert: In the correct contract, a non-Owner calling Command(...) must NOT decrease the contract's balance via withdraw — i.e., balance after is >= balance before minus 0 (it cannot be drained by non-Owner).
        // We express this as: after >= before
        assertTrue(after >= before);
    }
}

