pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: attacker sends some value and targets an adversarial callee
    function testFuzz_property(address callee, uint256 sendAmt) public {
        // keep fuzzed domain reasonable: nonzero amount up to 1e18
        vm.assume(callee != address(0));
        sendAmt = bound(sendAmt, 0, 1 ether);

        // deploy an adversarial helper that will accept ETH but then try to make c.withdraw() happen
        // We need a helper to act as an address with code; deploy a simple receiver that does nothing on call
        // but we'll use it as the target of Command's call data. The key adversarial behavior is that
        // a non-owner could later call withdraw on the mutant; we simulate a non-owner calling Command
        // by using vm.prank below.
        Receiver r = new Receiver();

        // fund the contract c so that withdraw has a balance to transfer
        vm.deal(address(this), 1 ether);
        payable(address(c)).transfer(0); // no-op to silence unused-wire; actually not needed
        // send some ether into c to create nonzero balance; use sendAmt so fuzzer picks value
        vm.deal(address(this), sendAmt);
        if (sendAmt > 0) {
            payable(address(c)).transfer(sendAmt);
        }

        // craft calldata for a benign call to the receiver (empty data)
        bytes memory data = "";

        // act as a non-owner caller (pick an address different from c.Owner())
        address nonOwner = address(0xBEEF);
        // ensure nonOwner is not Owner
        vm.assume(nonOwner != address(c.Owner()));

        // record pre-call balance
        uint256 beforeBal = address(c).balance;

        // perform Command from nonOwner to the deployed receiver, forwarding no value
        vm.prank(nonOwner);
        // use try/catch to capture any revert differences (though Command in C does not revert on call failures)
        bool ok;
        try c.Command(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // record after-call balance
        uint256 afterBal = address(c).balance;

        // General rule (asserted): In the reference, after Command from a non-owner, the contract balance remains the same
        // (only Owner can withdraw; Command should not change c.balance). The mutant that removes the withdraw-owner check
        // can allow a later non-owner-triggered withdraw to move funds to Owner; thus there exist inputs where afterBal < beforeBal.
        // We assert that balance did not decrease here (this holds for the reference for all inputs; mutant will fail for some).
        assertTrue(afterBal >= beforeBal);
    }
}

