pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller (an address) and an amount of ETH to fund the contract and use in Command
    function testFuzz_property(address caller, uint256 fundAmount) public {
        // keep domain wide but meaningful
        vm.assume(caller != address(0));
        fundAmount = bound(fundAmount, 0, 1 ether);

        // deploy adversarial callee that always reverts on receive / fallback
        Reverter rev = new Reverter();

        // fund caller so they can send ETH in Command
        vm.deal(caller, fundAmount + 1 ether);

        // also fund the contract itself with some ETH so withdraw has something to transfer
        vm.deal(address(this), 1 ether);
        // send some ETH into c from this test contract
        (bool ok,) = address(c).call{value: 0.5 ether}('');
        require(ok);

        // record pre-state
        uint256 before = address(c).balance;

        // call Command as the arbitrary caller, forwarding fundAmount and targeting the reverter
        vm.prank(caller);
        // craft empty data; call will revert inside target but Command ignores the revert (low-level call)
        try c.Command(address(rev), "") {
            // call returned (in reference this will succeed because low-level call failures don't bubble)
        } catch {
            // shouldn't reach here because Command does not revert on callee revert (it uses call())
        }

        // After this sequence: in the reference, only Owner can withdraw, so non-Owner caller cannot change c's balance.
        // The single universal assertion: c's balance has not decreased below what it was before the Command call.
        // This must hold for ALL admissible inputs in the reference; the mutant that removes Owner check on withdraw
        // can allow a non-Owner caller to later invoke withdraw (or have withdraw invoked) and empty the contract,
        // making this assertion fail for some fuzzed inputs.
        uint256 after = address(c).balance;
        assertTrue(after >= before);
    }
}

