pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an arbitrary caller and an arbitrary amount to send via Command to an adversarial helper
    function testFuzz_property(address caller, uint256 sendAmount) public {
        // keep sendAmount reasonable (non-zero and not insanely large)
        vm.assume(caller != address(0));
        sendAmount = bound(sendAmount, 1, 1 ether);

        // deploy an adversarial helper that accepts the call (no revert) so Command will succeed
        // The difference we're targeting: mutant allows ANY caller to call withdraw; reference only Owner.
        // We will fund the contract, call Command from 'caller' (to ensure non-Owner interaction occurs),
        // then have the same non-Owner attempt to call withdraw. In the reference, this withdraw must revert
        // (or at least not transfer out balance). We observe address(c).balance to detect transfer.

        Adversary adv = new Adversary();

        // fund the caller so they can send value
        vm.deal(caller, sendAmount + 1);
        // fund the contract initial balance (from Owner, setUp deployer is test contract's msg.sender, which is this test),
        // but we need to send some ETH into c so there's a non-zero balance to be stolen by a buggy withdraw.
        uint256 initialContractBalance = 0.5 ether;
        vm.deal(address(this), initialContractBalance);
        // send ETH into c from the test contract (which is the Owner)
        c.Command{value: initialContractBalance}(address(adv), "");

        // ensure contract has the expected initial balance
        assert(address(c).balance == initialContractBalance);

        // Now perform a Command call from 'caller' to the adversary (simulate arbitrary non-Owner interaction)
        vm.prank(caller);
        // caller forwards a small value (sendAmount) with the call
        try c.Command{value: sendAmount}(address(adv), "") {
            // call succeeded; we don't need to assert on this
        } catch {
            // if Command reverts for this caller, that's fine; the property still should hold that non-Owner cannot withdraw
        }

        // After that interaction, have the same 'caller' attempt to call withdraw.
        // In the reference, withdraw should only be allowed for Owner, so this attempt must NOT reduce address(c).balance.
        vm.prank(caller);
        // capture balance before
        uint256 before = address(c).balance;
        // attempt withdraw; mutant would allow caller to drain to Owner, reducing address(c).balance
        // we call and ignore revert to let both behaviors be observed via balance
        try c.withdraw{value:0}() {
        } catch {
        }
        uint256 after = address(c).balance;

        // Single assertion: reference guarantees non-Owner withdraw does not change contract balance for ANY caller and amount.
        // So for all admissible inputs, before == after must hold. The mutant (which removed the Owner check) will allow
        // some caller to make before != after (draining to Owner), so the test will fail on the mutant for some fuzzed inputs.
        assertTrue(before == after);
    }
}

contract Adversary {
    // accept any call, do nothing
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the test
    function run(address payable ownerLike, uint256 send1, uint256 send2) public payable {
        // ensure this test contract has enough balance to forward ETH
        require(address(this).balance >= send1 + send2);

        // 1) fund the target contract c by calling multiplicate with some value
        // multiplicate will transfer out only in some cases, but it is payable and can increase c's balance
        c.multiplicate{value: send1}(ownerLike);

        // 2) also call Command to forward more value into c (Command forwards msg.value to an arbitrary call)
        // use empty data so it effectively just forwards ETH
        c.Command{value: send2}(address(0), "");

        // Precondition: require that this contract is the Owner of c for withdraw to be callable successfully
        // We express this by calling c.Owner() and requiring it equals address(this)
        require(c.Owner() == address(this));

        // Now call withdraw as the owner; this is the deciding call whose behavior differs between P and M
        c.withdraw();

        // On original P: withdraw transfers the entire balance even if balance is zero (no extra check), so it will succeed
        // On mutant M: withdraw requires address(this).balance > 0 and would revert if balance is zero.
        // We assert that after calling withdraw, the contract c's balance is zero (i.e., withdraw succeeded and drained funds)
        assert(address(c).balance == 0);
    }

    // receive to accept forwarded ETH so this test contract can hold funds to call payable c functions
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition: test owner behavior for any balance
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        // On the original contract P, Owner can call withdraw and it will not revert
        // (even when the contract balance is zero). The mutated M adds a require(balance>0)
        // so withdraw can revert when the balance is zero. We express that withdraw must not revert.
        assert(reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require that this contract is the Owner of c
        require(c.Owner() == address(this));

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        // In the original contract P, Owner can call withdraw and it will not revert
        // (it executes even if the contract balance is zero). The mutant adds a
        // require(address(this).balance > 0) which can cause a revert when balance==0.
        assert(reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address owner;
    constructor(C _c) { c = _c; owner = c.Owner(); }
    function run() public payable {
        // No precondition: we test behavior for the Owner caller
        // Ensure this contract is the Owner by requiring Owner equals address(this)
        require(owner == address(this));
        bool reverted;
        try c.withdraw{value: 0}() { reverted = false; } catch { reverted = true; }
        // Property: if caller is the Owner, withdraw must not revert
        assert(reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition: we must call withdraw as the Owner; the deployer of C was the Owner.
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        // General rule: when caller is the contract Owner (the original contract's Owner is the deployer of C),
        // calling withdraw must not revert even if c's balance is zero. We observe only reverted and address(c).balance.
        assert(!(address(c).balance == 0 && reverted));
    }
    receive() external payable {}
}

