pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: amount forwarded to Command and an arbitrary bytes payload length selector
    function testFuzz_property(uint256 value, uint256 payloadSize) public {
        // Keep bounds wide but reasonable
        vm.assume(value <= 1 ether);
        payloadSize = bound(payloadSize, 0, 64);

        // Deploy an adversarial callee that will revert when called
        Reverter r = new Reverter();

        // Fund an external actor so it can send value via Command
        address attacker = address(0xABBA);
        vm.deal(attacker, value + 1 ether);

        // Prepare arbitrary payload (fuzzer-chosen size) to forward
        bytes memory payload = new bytes(payloadSize);
        for (uint256 i = 0; i < payloadSize; i++) {
            payload[i] = bytes1(uint8(i));
        }

        // Have the attacker call Command on c, forwarding `value` to the callee address r
        vm.prank(attacker);
        // The call forwards ETH and calldata to r; r will revert. Use try/catch to record success.
        bool ok;
        try c.Command{value: value}(address(r), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property to assert on C: after this interaction, the contract's Owner should still be
        // able to withdraw the contract balance (i.e., calling withdraw should NOT revert on the reference
        // implementation for any inputs). We express this by attempting withdraw and checking it does NOT revert.
        // We must run withdraw from Owner (deployer of c). setUp() made msg.sender the test contract, but Owner was msg.sender at construction = this test contract's address.
        // So call withdraw as this contract (no prank needed).
        bool withdrawOk;
        try c.withdraw{value: 0}() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The single assertion: the reference contract should always allow withdraw to succeed (true) for all inputs.
        // The mutant that adds `require(address(this).balance > 0)` can make withdraw revert when balance is zero,
        // which can happen depending on how the forwarded call behaved. The fuzzer will find such inputs and fail the mutant.
        assertTrue(withdrawOk);
    }
}

