    // fuzz the amount to forward and arbitrary calldata (as bytes). We need at least one param.
    function testFuzz_property(uint256 value, bytes memory data) public {
        // keep value small enough to fund
        uint256 amt = bound(value, 0, 1 ether);

        // deploy a helper that REQUIRES non-zero value and will revert on zero-value calls
        Requirer req = new Requirer();

        // fund this test contract so it can be Owner and send value through c
        vm.deal(address(this), 1 ether);

        // ensure caller is Owner (c sets Owner = msg.sender at construction; setUp used test contract)
        // call Command as Owner, forwarding amt to the helper address
        bool ok;
        try c.Command{value: amt}(address(req), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: The reference forwards msg.value to the callee, so if the callee reverts on zero-value
        // then any non-zero amt should make the call succeed; the mutant that drops the value will make the call fail
        // for some inputs (when amt>0). We assert the property that when amt>0 the call succeeds.
        // This assertion holds for the reference contract for all inputs, and the buggy mutant (which calls with zero value)
        // will fail for some inputs (those with amt>0). Assert exactly one condition reading c via its external behavior.
        assertTrue(!(amt > 0) || ok);
    }
}

// adversarial helper: reverts if called with zero value, otherwise does nothing (accepts funds)
contract Requirer {
    fallback() external payable {
        if (msg.value == 0) revert("zero value not allowed");
    }
    receive() external payable {
        if (msg.value == 0) revert("zero value not allowed");
    }
}
